package com.example.topic.persistence;

import com.baomidou.mybatisplus.annotation.FieldFill;
import com.baomidou.mybatisplus.annotation.IdType;
import com.baomidou.mybatisplus.annotation.TableField;
import com.baomidou.mybatisplus.annotation.TableId;
import com.baomidou.mybatisplus.annotation.TableLogic;
import com.baomidou.mybatisplus.annotation.TableName;
import com.baomidou.mybatisplus.annotation.Version;

import java.time.LocalDateTime;

@TableName("topic")
public class TopicEntity {

    @TableId(type = IdType.AUTO)
    private Long id;
    private String slug;
    private String title;
    private String category;
    private String status;
    @TableLogic
    private Integer deleted;
    @Version
    private Integer version;
    @TableField(fill = FieldFill.INSERT)
    private LocalDateTime createdAt;
    @TableField(fill = FieldFill.INSERT_UPDATE)
    private LocalDateTime updatedAt;

    // getter / setter 省略
}

package com.example.topic.config;

import com.baomidou.mybatisplus.annotation.DbType;
import com.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor;
import com.baomidou.mybatisplus.extension.plugins.inner.OptimisticLockerInnerInterceptor;
import com.baomidou.mybatisplus.extension.plugins.inner.PaginationInnerInterceptor;
import org.mybatis.spring.annotation.MapperScan;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@MapperScan("com.example.topic.persistence")
public class MybatisPlusConfig {

    @Bean
    public MybatisPlusInterceptor mybatisPlusInterceptor() {
        MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor();
        PaginationInnerInterceptor pagination =
                new PaginationInnerInterceptor(DbType.MYSQL);
        pagination.setMaxLimit(500L);
        pagination.setOverflow(false);
        interceptor.addInnerInterceptor(pagination);
        interceptor.addInnerInterceptor(new OptimisticLockerInnerInterceptor());
        return interceptor;
    }
}

package com.example.topic.application;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.example.topic.persistence.TopicEntity;
import com.example.topic.persistence.TopicMapper;
import org.springframework.stereotype.Service;

@Service
public class TopicService {

    private final TopicMapper topicMapper;

    public TopicService(TopicMapper topicMapper) {
        this.topicMapper = topicMapper;
    }

    public Page<TopicEntity> pagePublished(String category, long current, long size) {
        LambdaQueryWrapper<TopicEntity> query = new LambdaQueryWrapper<TopicEntity>()
                .eq(TopicEntity::getStatus, "published")
                .eq(category != null && !category.isBlank(),
                        TopicEntity::getCategory, category)
                .orderByDesc(TopicEntity::getUpdatedAt);
        return topicMapper.selectPage(new Page<>(current, size), query);
    }

    public boolean rename(Long id, String title, int expectedVersion) {
        TopicEntity patch = new TopicEntity();
        patch.setId(id);
        patch.setTitle(title);
        patch.setVersion(expectedVersion);
        return topicMapper.updateById(patch) == 1;
    }
}
